css:
@font-face {
  font-family: Lato;
  src: url("/site-assets/combined/lato-400.ttf") format("truetype");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: Lato;
  src: url("/site-assets/combined/lato-700.ttf") format("truetype");
  font-weight: 600 800;
  font-display: swap;
}
@font-face {
  font-family: Nunito;
  src: url("/site-assets/advisory/nunito.ttf") format("truetype");
  font-weight: 400;
  font-display: swap;
}
/* Desktop dimensions follow the approved 793 × 1983 composition. Mobile uses
   readable type and controls, rather than shrinking the desktop composition. */
:root {
  font-size: min(calc(var(--final-viewport, 100vw) / 793), 2px);
  --ink: #321068;
  --paper: #fcfbf8;
  --muted: #6255a3;
  --purple: #401078;
  --line: #ded9e9;
  --font-body: Lato, Arial, sans-serif;
  --navy-accent: #401078;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 20rem;
  scrollbar-color: #aa94cf #fcfbf8;
}
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 12rem/1.4 var(--font-body);
}
::selection {
  background: #e5d5f4;
  color: #321068;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
textarea {
  font: inherit;
}
button,
a,
summary {
  touch-action: manipulation;
}
button,
summary {
  cursor: pointer;
}
input,
textarea {
  caret-color: var(--purple);
}
:focus-visible {
  outline: 2rem solid #148c99;
  outline-offset: 4rem;
}
h1,
h2,
h3,
p,
figure {
  margin: 0;
}
h1,
h2,
h3 {
  font-family: Nunito, Lato, Arial, sans-serif;
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.04em;
}
h2 {
  font-size: 39rem;
}
.client-site {
  position: relative;
  overflow: clip;
  max-width: 1586px;
  margin: auto;
  background: #fcfbf8;
}
.final-wrap {
  width: 695rem;
  max-width: calc(100% - 100rem);
  margin-inline: auto;
}
.eyebrow {
  font-size: 7rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #6125aa;
  margin-bottom: 14rem;
  line-height: 1.3;
}
.body-copy,
.hero-intro,
.service-intro {
  color: var(--muted);
  font-size: 12rem;
  line-height: 1.42;
}
.final-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 10rem;
  min-height: 30rem;
  padding: 7rem 16rem;
  white-space: nowrap;
  border: 1rem solid #491a78;
  border-radius: 2rem;
  background: linear-gradient(110deg, #43117d, #35106a);
  color: white;
  font: 400 10rem/1.3 var(--font-body);
  box-shadow: 0 3rem 7rem #33105c18;
  transition:
    background 0.18s,
    box-shadow 0.18s;
}
.final-button:hover {
  background: #55208a;
  box-shadow: 0 4rem 10rem #33105c25;
}
.final-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.final-button span,
.text-link span,
.service-arrow {
  font:
    16rem/1 Arial,
    sans-serif;
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9rem;
  font-size: 9rem;
  font-weight: 600;
  min-height: 30rem;
}
.final-skip {
  position: fixed;
  top: -100px;
  left: 16px;
  z-index: 20;
  background: white;
  padding: 12px;
  font-size: 16px;
}
.final-skip:focus {
  top: 12px;
}
/* Refreshed artwork preserves the approved atlas coordinates. Page text,
   navigation, approach icons and forms are native. */
.reference-art {
  display: block;
  background-image: url("/site-assets/advisory/refreshed-artwork.png");
  background-repeat: no-repeat;
  background-size: 793rem 1983rem;
}
/* Supplied replacements are complete images, rather than atlas windows.
   Higher specificity keeps their framing intact in mobile layouts. */
.reference-art.hero-art,
.reference-art.hero-wash,
.reference-art.hero-handwriting,
.reference-art.finder-handwriting,
.reference-art.brief-art,
.reference-art.workshop-photo,
.reference-art.contact-handwriting,
.reference-art.footer-handwriting {
  background-size: 100% 100%;
  background-position: center;
}
.reference-art.hero-art {
  background-image: url("/site-assets/advisory/elements/hero-collage-implement.png");
}
.reference-art.hero-wash {
  background-image: url("/site-assets/advisory/elements/hero-colour-wash.png");
}
.reference-art.hero-handwriting {
  background-image: url("/site-assets/advisory/elements/hero-handwriting.png");
}
.reference-art.finder-handwriting {
  background-image: url("/site-assets/advisory/elements/check-in-handwriting.png");
}
.reference-art.brief-art {
  background-image: url("/site-assets/advisory/elements/decision-paper-composition.png");
}
.reference-art.workshop-photo {
  background-image: url("/site-assets/advisory/elements/dr-ramzi-planning.png");
  background-size: cover;
  background-position: center;
}
.reference-art.contact-handwriting {
  background-image: url("/site-assets/advisory/elements/contact-handwriting-and-leaves.png");
}
.reference-art.footer-handwriting {
  background-image: url("/site-assets/advisory/elements/footer-handwriting.png");
}
.final-header {
  height: 84rem;
  display: flex;
  align-items: center;
  position: relative;
  z-index: 2;
  gap: 22rem;
}
.brand-art {
  display: block;
  width: 84rem;
  height: 66rem;
  flex: none;
}
.brand-art,
.footer-art {
  position: relative;
  overflow: hidden;
}
/* Crop the supplied 1125px canvas without resampling or redrawing the mark. */
.site-logo {
  display: block;
  position: absolute;
  width: 189.394%;
  max-width: none;
  height: auto;
  left: -44.613%;
  top: -55.365%;
}
.desktop-nav {
  display: flex;
  gap: 24rem;
  align-items: center;
  position: absolute;
  left: 280rem;
  top: 28rem;
  font-size: 9rem;
}
.desktop-nav a {
  padding: 7rem 0;
  white-space: nowrap;
}
.active {
  text-decoration: underline;
  text-underline-offset: 5rem;
}
.header-button {
  position: absolute;
  right: -11rem;
  top: 25rem;
  width: 94rem;
  min-height: 28rem;
  padding: 6rem 10rem;
  gap: 6rem;
  font-size: 9rem;
}
.final-hero {
  height: 308rem;
  position: relative;
}
.client-site main > section + section {
  margin-top: 28rem;
}
.hero-copy {
  position: relative;
  z-index: 1;
  padding: 18rem 0 0 50rem;
  width: 388rem;
}
.hero-copy .eyebrow {
  margin-bottom: 16rem;
  white-space: nowrap;
}
.hero-copy h1 {
  font-size: 53rem;
  line-height: 0.87;
  letter-spacing: -0.045em;
  white-space: nowrap;
}
.hero-copy h1 span {
  background: linear-gradient(
    95deg,
    #351063 0%,
    #54219d 47%,
    #8a73bd 68%,
    #00aeb8 98%
  );
  color: transparent;
  background-clip: text;
}
.hero-intro {
  margin-top: 1rem;
  width: 338rem;
  font-size: 13rem;
}
.hero-actions {
  display: flex;
  align-items: center;
  gap: 17rem;
  margin-top: 12rem;
}
.hero-actions .final-button {
  width: 110rem;
}
.hero-art {
  mask-image: linear-gradient(90deg, transparent, #000 22rem);
  position: absolute;
  right: 0;
  top: -14rem;
  width: 405rem;
  height: 322rem;
  background-position: -388rem -40rem;
}
.hero-wash {
  position: absolute;
  left: 197rem;
  bottom: 20rem;
  width: 191rem;
  height: 75rem;
  background-position: -197rem -267rem;
  mask-image: linear-gradient(to bottom, transparent, #000 20%);
}
.hero-handwriting {
  mix-blend-mode: multiply;
  width: 85rem;
  height: 74rem;
  background-position: -45rem -273rem;
  margin-left: -5rem;
  margin-top: 7rem;
}
.problem-section {
  display: grid;
  grid-template-columns: 285rem 381rem;
  gap: 30rem;
  background: #f2ecfc;
  min-height: 207rem;
  padding: 17rem 48rem 16rem 50rem;
}
.problem-copy {
  padding-top: 5rem;
}
.problem-copy .eyebrow {
  margin-bottom: 12rem;
}
.problem-copy h2 {
  font-size: 36rem;
  line-height: 0.87;
}
.problem-copy .body-copy {
  margin-top: 12rem;
  width: 266rem;
}
.small-rule {
  display: block;
  width: 36rem;
  height: 1rem;
  background: #8970b1;
  margin-top: 12rem;
}
.finder-panel {
  position: relative;
  background: #fcfbf8;
  padding: 17rem 26rem 13rem;
  min-width: 0;
}
.finder-handwriting {
  mix-blend-mode: multiply;
  filter: brightness(1.04);
  position: absolute;
  right: 6rem;
  bottom: 11rem;
  width: 74rem;
  height: 86rem;
  background-position: -665rem -453rem;
  pointer-events: none;
}
.client-site .finder-panel .form-runner {
  position: relative;
  z-index: 1;
  font-size: 9rem;
  color: #514294;
  gap: 8rem;
}
.client-site .finder-panel .form-runner h3 {
  font-family: Nunito, Lato, Arial, sans-serif;
  font-size: 16rem;
  line-height: 1.1;
  letter-spacing: -0.035em;
  color: #321068;
}
.client-site .finder-panel .form-runner > .muted {
  font-size: 9rem;
}
.client-site .finder-panel .form-runner .stack {
  gap: 7rem;
}
.client-site .finder-panel .form-runner .button {
  font-size: 9rem;
  min-height: 30rem;
  border-radius: 2rem;
  padding: 7rem 13rem;
  border-color: #cec2e2;
}
.client-site .finder-panel .form-runner .row {
  gap: 9rem;
}
.client-site .finder-panel .form-runner .field {
  font-size: 10rem;
  gap: 5rem;
}
.client-site .finder-panel .form-runner textarea {
  min-height: 70rem;
  padding: 9rem;
  font-size: 11rem;
}
.client-site .finder-panel .form-runner ul {
  padding-left: 16rem;
  margin: 0;
}
.client-site .finder-panel .form-runner .muted {
  font-size: 8rem;
}
.radio-form > .muted {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}
.radio-choices {
  border: 0;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 4rem;
}
.radio-choice {
  display: flex;
  align-items: center;
  gap: 9rem;
  min-height: 16rem;
  cursor: pointer;
  padding-right: 48rem;
  font-size: 9rem;
  line-height: 1.3;
}
.radio-choice input {
  appearance: none;
  width: 13rem;
  height: 13rem;
  margin: 0;
  flex: none;
  border: 1.2rem solid #7460b0;
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-content: center;
}
.radio-choice input:checked::after {
  content: "";
  width: 7rem;
  height: 7rem;
  border-radius: 50%;
  background: #572090;
}
.radio-actions {
  display: flex;
  align-items: center;
  gap: 15rem;
  margin-top: 10rem;
}
.radio-actions .final-button {
  width: 96rem;
}
.radio-actions small {
  font-size: 8rem;
  white-space: nowrap;
  color: #7261ac;
}
.client-site .finder-panel .radio-form .row {
  margin-top: 3rem;
}
.services-section {
  min-height: 255rem;
  padding-top: 18rem;
  padding-bottom: 17rem;
}
.section-heading {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 55rem;
}
.services-section .eyebrow {
  margin-bottom: 11rem;
}
.services-section h2,
.services-section h1 {
  font-size: 40rem;
  line-height: 0.84;
}
.section-heading .service-intro {
  font-size: 11rem;
  width: 270rem;
  max-width: 100%;
  margin-top: 12rem;
}
.service-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1rem solid var(--line);
  margin-top: 15rem;
}
.service-row {
  display: grid;
  grid-template-columns: 34rem 1fr;
  gap: 8rem 11rem;
  align-content: start;
  position: relative;
  padding: 11rem 6rem 4rem 0;
  min-width: 0;
}
.service-row + .service-row {
  border-left: 1rem solid var(--line);
  padding-left: 9rem;
}
.service-number {
  width: 33rem;
  height: 33rem;
  border: 1rem solid #e4dbf1;
  border-radius: 50%;
  background: #f5f0fb;
  display: grid;
  place-items: center;
  font-size: 13rem;
}
.service-row h3 {
  font: 600 11rem/1.2 var(--font-body);
  letter-spacing: -0.025em;
  padding-top: 4rem;
}
.service-arrow {
  position: absolute;
  right: 5rem;
  top: 16rem;
  font-size: 14rem;
}
.service-row p {
  grid-column: 2;
  color: var(--muted);
  font-size: 9rem;
  line-height: 1.34;
  margin-top: 0;
}
.service-row:hover h3 {
  text-decoration: underline;
  text-underline-offset: 3rem;
}
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  html:not([data-motion="off"]) .service-arrow,
  html:not([data-motion="off"]) .service-number {
    transition: transform 180ms cubic-bezier(0.23, 1, 0.32, 1);
  }
  html:not([data-motion="off"]) .service-row:hover .service-arrow {
    transform: translateX(3rem);
  }
  html:not([data-motion="off"]) .service-row:hover .service-number {
    transform: translateY(-2rem);
  }
}
.brief-section {
  min-height: 276rem;
  background: #fff;
  position: relative;
  padding: 26rem 50rem 20rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: center;
  gap: 32rem;
}
.brief-copy {
  position: relative;
  z-index: 1;
}
.brief-copy .eyebrow {
  margin-bottom: 13rem;
}
.brief-copy h2 {
  font-size: 45rem;
  line-height: 0.85;
  white-space: nowrap;
}
.brief-copy .body-copy {
  margin-top: 17rem;
  max-width: 259rem;
}
.brief-art {
  position: relative;
  width: 100%;
  height: auto;
  aspect-ratio: 456 / 276;
}
.decision-builder {
  margin-top: 14rem;
}
.decision-builder summary {
  list-style: none;
  width: max-content;
}
.decision-builder summary::-webkit-details-marker {
  display: none;
}
.decision-builder[open] {
  width: 330rem;
  max-width: 100%;
}
.decision-builder[open] .finder-panel {
  margin-top: 14rem;
  padding: 18rem;
  box-shadow: 0 5rem 20rem #34146612;
}
.approach-section {
  padding-block: 24rem;
  background: #e7f6f8;
}
.approach-section .eyebrow {
  margin-bottom: 11rem;
}
.approach-section h2 {
  font-size: 39rem;
  line-height: 1.04;
}
.approach-section .section-heading {
  gap: 40rem;
  align-items: end;
}
.approach-stages {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 18rem;
  padding: 16rem 0 0;
  margin: 18rem 0 0;
  border-top: 1rem solid var(--line);
  list-style: none;
}
.approach-stages li {
  display: grid;
  grid-template-rows: 64rem auto auto auto;
  grid-row: span 4;
  grid-template-rows: subgrid;
  row-gap: 7rem;
  text-align: left;
  min-width: 0;
}
.stage-icon {
  transition: transform 220ms cubic-bezier(.23, 1, .32, 1);
  display: block;
  object-fit: contain;
  width: 58rem;
  height: 56rem;
  margin: 0;
}
.approach-stages h3 {
  font: 600 16rem/1.2 var(--font-body);
  letter-spacing: 0;
  margin-top: 0;
}
.approach-stages p {
  font-size: 11rem;
  color: var(--muted);
  line-height: 1.5;
  margin: 0;
}
.approach-stages .stage-purpose {
  font-size: 12rem;
  line-height: 1.4;
  color: var(--ink);
}
.practice-section {
  display: grid;
  grid-template-columns: 387rem 406rem;
  min-height: 236rem;
  background: #fff;
}
.practice-copy {
  padding: 20rem 22rem 16rem 50rem;
}
.practice-copy .eyebrow {
  margin-bottom: 13rem;
}
.practice-copy h2 {
  font-size: 33rem;
  line-height: 0.9;
  white-space: normal;
}
.practice-copy .body-copy {
  margin-top: 10rem;
  font-size: 11rem;
  line-height: 1.43;
}
.practice-copy .final-button {
  margin-top: 9rem;
  min-width: 120rem;
}
.practice-photo {
  min-width: 0;
  width: 85%;
  align-self: center;
  justify-self: center;
  padding-block: 24rem;
}
.workshop-photo {
  width: 100%;
  height: auto;
  aspect-ratio: 406 / 217;
  background-position: -387rem -1376rem;
}
.practice-photo figcaption {
  font-size: 7rem;
  color: #7a60a5;
  padding-top: 3rem;
}
.contact-section {
  position: relative;
  background: #f2ecfc;
  display: grid;
  grid-template-columns: 250rem 304rem;
  gap: 32rem;
  padding: 18rem 50rem 16rem;
  min-height: 203rem;
}
.contact-copy .eyebrow {
  margin-bottom: 13rem;
}
.contact-copy h2 {
  font-size: 44rem;
  line-height: 0.8;
}
.contact-copy .body-copy {
  font-size: 11rem;
  line-height: 1.4;
  margin-top: 15rem;
}
.final-contact-form {
  padding-top: 2rem;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.form-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9rem;
}
.form-fields label {
  display: flex;
  flex-direction: column;
  gap: 3rem;
  font-size: 8rem;
  color: #6551a2;
}
.form-fields input,
.form-fields textarea {
  width: 100%;
  min-width: 0;
  border: 1rem solid #d4cde5;
  border-radius: 2rem;
  background: #fefefe;
  color: var(--ink);
  font-size: 8rem;
  line-height: 1.3;
  padding: 6rem;
}
.form-fields input {
  height: 23rem;
}
.form-fields textarea {
  height: 63rem;
  resize: vertical;
}
.form-fields input::placeholder,
.form-fields textarea::placeholder {
  color: #8072b3;
  opacity: 1;
}
.message-field {
  grid-column: 1/-1;
}
.contact-actions {
  display: flex;
  align-items: center;
  gap: 11rem;
  margin-top: 12rem;
  white-space: nowrap;
}
.contact-actions .final-button {
  font-size: 9rem;
  padding: 7rem 12rem;
  min-height: 28rem;
  flex: none;
}
.email-note {
  font-size: 6.5rem;
  color: #7360a8;
}
.contact-feedback {
  font-size: 11rem;
  padding-top: 10rem;
  white-space: normal;
}
.contact-feedback a {
  text-decoration: underline;
}
.contact-handwriting {
  mix-blend-mode: multiply;
  filter: brightness(1.04);
  position: absolute;
  right: 0;
  bottom: 0;
  width: 142rem;
  height: 176rem;
  background-position: -651rem -1639rem;
  pointer-events: none;
}
.final-footer {
  min-height: 168rem;
  padding: 26rem 50rem 30rem;
  background: linear-gradient(115deg, #381065, #451774 55%, #351061);
  color: #eee5fa;
}
.footer-main {
  display: flex;
  align-items: center;
  min-height: 64rem;
  gap: 24rem;
  position: relative;
}
.footer-art {
  display: block;
  filter: brightness(0) invert(1);
  flex: none;
  width: 96rem;
  height: 75rem;
}
.footer-main nav {
  display: flex;
  gap: 24rem;
  margin-left: 62rem;
  font-size: 9rem;
  white-space: nowrap;
}
.footer-links {
  display: flex;
  align-items: center;
  gap: 22rem;
  padding-left: 23rem;
  border-left: 1rem solid #8d66ab;
  font-size: 8rem;
  white-space: nowrap;
}
.footer-links button {
  border: 0;
  padding: 0;
  background: none;
  color: inherit;
  font: inherit;
}
.footer-handwriting {
  filter: grayscale(1) contrast(3);
  mix-blend-mode: screen;
  position: absolute;
  right: -20rem;
  top: -5rem;
  width: 83rem;
  height: 86rem;
  background-position: -679rem -1836rem;
}
.footer-bottom {
  display: flex;
  justify-content: space-between;
  font-size: 7rem;
  margin-top: 20rem;
}
.privacy-dialog {
  width: min(90vw, 600px);
  border: 0;
  border-radius: 6px;
  padding: 32px;
  background: #fcfbf8;
  color: #321068;
  font-size: 16px;
  line-height: 1.6;
}
.privacy-dialog::backdrop {
  background: #230d4266;
}
.privacy-dialog h2 {
  font-size: 36px;
  margin-bottom: 18px;
}
.privacy-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 20px;
}
.privacy-actions button {
  font-size: 14px;
  min-height: 44px;
}
.privacy-actions #site-motion {
  border: 0;
  background: none;
  color: inherit;
